#!/bin/bash
# Frequency-resolution ablation + output-layer ablation (3 subjects each).
# All ablations use a single fixed seed (--seed 42), matching Appendix B.5.
# Requires the ablation spectrograms generated by gen_ablation_data.py first.

set -e
cd "$(dirname "$0")"

PY="${PY:-python}"
ABL_ROOT="${BCI_ABLATION_DIR:-../data_ablation}"

echo "=== Frequency-resolution ablation 1/3: bandpass only (no Morlet, 1 band) ==="
$PY -u run_direct.py --subject all --seed 42 --data-root "$ABL_ROOT/freq_1band" --out ../results/ablation_freq_1band

echo "=== Frequency-resolution ablation 2/3: Morlet 20 band ==="
$PY -u run_direct.py --subject all --seed 42 --data-root "$ABL_ROOT/freq_20band" --out ../results/ablation_freq_20band

echo "=== Frequency-resolution ablation 3/3: Morlet 10 band ==="
$PY -u run_direct.py --subject all --seed 42 --data-root "$ABL_ROOT/freq_10band" --out ../results/ablation_freq_10band

echo "=== Output-layer ablation: single-point output ==="
$PY -u run_direct.py --subject all --seed 42 --output single --out ../results/ablation_single

echo "=== All ablations done ==="
